INSERT INTO public.question_translations (question_key, part, locale, prompt, choices, explanation) VALUES
  ('1.1-Q1', 'A', 'en', 'Fundamental analysis seeks to determine:', '[{"id": "a", "label": "The technical trend of the market"}, {"id": "b", "label": "The intrinsic value of an asset"}, {"id": "c", "label": "Trading volumes"}, {"id": "d", "label": "Future volatility"}]'::jsonb, 'It relies on economic and financial factors to estimate "fair value."'),
  ('1.1-Q10', 'A', 'en', 'An investor who uses fundamental analysis aims to:', '[{"id": "a", "label": "Profit from ultra-short-term fluctuations"}, {"id": "b", "label": "Exploit divergences between market price and intrinsic value"}, {"id": "c", "label": "Follow chart trends"}, {"id": "d", "label": "Ignore economic data"}]'::jsonb, 'The objective is to buy undervalued assets and sell overvalued ones.'),
  ('1.1-Q11', 'A', 'en', 'The "intrinsic value" of a currency depends notably on:', '[{"id": "a", "label": "Market orders"}, {"id": "b", "label": "The economic health of the issuing country"}, {"id": "c", "label": "The number of transactions"}, {"id": "d", "label": "The weather"}]'::jsonb, 'Economic health (GDP, inflation, etc.) determines the value of a currency.'),
  ('1.1-Q12', 'A', 'en', 'Why is fundamental analysis important for risk management?', '[{"id": "a", "label": "It eliminates all risk of loss"}, {"id": "b", "label": "It identifies assets supported by solid fundamentals"}, {"id": "c", "label": "It guarantees high returns"}, {"id": "d", "label": "It is risk-free"}]'::jsonb, 'Knowing the strength of the fundamentals allows for a better assessment of risk.'),
  ('1.1-Q13', 'A', 'en', 'Fundamental analysis is particularly well suited to markets:', '[{"id": "a", "label": "Illiquid markets"}, {"id": "b", "label": "Markets where prices are always fair"}, {"id": "c", "label": "Markets where inefficiencies can exist"}, {"id": "d", "label": "Markets where information is perfect"}]'::jsonb, 'Market inefficiencies create opportunities for fundamental analysis.'),
  ('1.1-Q14', 'A', 'en', 'The intrinsic value of a company is often estimated using:', '[{"id": "a", "label": "Market prices"}, {"id": "b", "label": "Discounted future cash flows"}, {"id": "c", "label": "Trading volumes"}, {"id": "d", "label": "Market rumors"}]'::jsonb, 'The DCF model is one of the most widely used valuation methods.'),
  ('1.1-Q15', 'A', 'en', 'In fundamental analysis, "convergence toward intrinsic value":', '[{"id": "a", "label": "Is instantaneous"}, {"id": "b", "label": "Can take time"}, {"id": "c", "label": "Never happens"}, {"id": "d", "label": "Depends on algorithms"}]'::jsonb, 'Markets can remain irrational for an extended period.'),
  ('1.1-Q2', 'A', 'en', 'According to fundamental analysis, the market price:', '[{"id": "a", "label": "Always coincides with intrinsic value"}, {"id": "b", "label": "Can temporarily deviate from intrinsic value"}, {"id": "c", "label": "Is independent of fundamentals"}, {"id": "d", "label": "Determines intrinsic value"}]'::jsonb, 'Markets are not perfectly efficient; divergences arise.'),
  ('1.1-Q3', 'A', 'en', 'One of the key principles of fundamental analysis is:', '[{"id": "a", "label": "Absolute market efficiency"}, {"id": "b", "label": "Long-term mean reversion"}, {"id": "c", "label": "The absence of risk"}, {"id": "d", "label": "Analyzing chart patterns alone"}]'::jsonb, 'The market price is expected to converge toward intrinsic value over the long term.'),
  ('1.1-Q4', 'A', 'en', 'Fundamental analysis is particularly useful for:', '[{"id": "a", "label": "High-frequency trading"}, {"id": "b", "label": "Long-term investment strategies"}, {"id": "c", "label": "Identifying support/resistance levels"}, {"id": "d", "label": "Candlestick pattern analysis"}]'::jsonb, 'It focuses on drivers of value over time.'),
  ('1.1-Q5', 'A', 'en', 'Which of the following is NOT an objective of fundamental analysis?', '[{"id": "a", "label": "Identifying overvalued assets"}, {"id": "b", "label": "Understanding market drivers"}, {"id": "c", "label": "Predicting the price in 5 minutes"}, {"id": "d", "label": "Managing risks"}]'::jsonb, 'Fundamental analysis is not designed to forecast ultra-short-term price fluctuations.'),
  ('1.1-Q6', 'A', 'en', 'Intrinsic value is based on:', '[{"id": "a", "label": "Market rumors"}, {"id": "b", "label": "Economic, financial, and qualitative factors"}, {"id": "c", "label": "Investor sentiment"}, {"id": "d", "label": "Market orders"}]'::jsonb, 'It is grounded in an in-depth analysis of fundamentals.'),
  ('1.1-Q7', 'A', 'en', 'The efficient market hypothesis is:', '[{"id": "a", "label": "Entirely true in all cases"}, {"id": "b", "label": "Challenged by fundamental analysis"}, {"id": "c", "label": "Irrelevant to the investor"}, {"id": "d", "label": "A mathematical law"}]'::jsonb, 'Fundamental analysis posits that markets are not always efficient.'),
  ('1.1-Q8', 'A', 'en', 'The principle of "mean reversion" implies that:', '[{"id": "a", "label": "Prices never return to their average"}, {"id": "b", "label": "Prices tend to revert toward their intrinsic value"}, {"id": "c", "label": "The average is always below the price"}, {"id": "d", "label": "The average price is the only benchmark"}]'::jsonb, 'This is one of the core pillars of fundamental analysis.'),
  ('1.1-Q9', 'A', 'en', 'Fundamental analysis differs from technical analysis because:', '[{"id": "a", "label": "It uses charts"}, {"id": "b", "label": "It focuses on underlying causes"}, {"id": "c", "label": "It is less reliable"}, {"id": "d", "label": "It applies only to equities"}]'::jsonb, 'Technical analysis focuses on prices and volumes, whereas fundamental analysis examines economic and financial fundamentals.'),
  ('1.2-Q1', 'A', 'en', 'An upside surprise in US GDP is generally:', '[{"id": "a", "label": "Bearish for the USD"}, {"id": "b", "label": "Bullish for the USD"}, {"id": "c", "label": "Neutral"}, {"id": "d", "label": "Impossible to anticipate"}]'::jsonb, 'Robust growth attracts capital flows and can keep policy rates elevated.'),
  ('1.2-Q10', 'A', 'en', 'A rise in oil prices generally benefits the:', '[{"id": "a", "label": "JPY"}, {"id": "b", "label": "CAD (Canada)"}, {"id": "c", "label": "EUR"}, {"id": "d", "label": "CHF"}]'::jsonb, 'Canada is a net oil exporter; higher oil prices improve its trade balance.'),
  ('1.2-Q11', 'A', 'en', 'In the US, "Average Hourly Earnings" measures:', '[{"id": "a", "label": "Total number of jobs"}, {"id": "b", "label": "Growth in wage earnings"}, {"id": "c", "label": "Labor force participation rate"}, {"id": "d", "label": "Productivity"}]'::jsonb, 'Strong wage growth can fuel inflation (wage-price spiral).'),
  ('1.2-Q12', 'A', 'en', 'Purchasing Managers'' Index (PMI) data are closely monitored because:', '[{"id": "a", "label": "They measure past inflation"}, {"id": "b", "label": "They provide an early indication of sectoral health"}, {"id": "c", "label": "They replace GDP"}, {"id": "d", "label": "They are published annually"}]'::jsonb, 'PMIs are leading indicators of economic activity.'),
  ('1.2-Q13', 'A', 'en', 'Which category of indicators includes interest rate decisions and forward guidance?', '[{"id": "a", "label": "Growth indicators"}, {"id": "b", "label": "Inflation indicators"}, {"id": "c", "label": "Monetary policy indicators"}, {"id": "d", "label": "Sentiment indicators"}]'::jsonb, 'These are events and communications that carry major fundamental market impact.'),
  ('1.2-Q14', 'A', 'en', 'A yield curve inversion (2Y > 10Y) is often interpreted as:', '[{"id": "a", "label": "A signal of strong economic growth"}, {"id": "b", "label": "A harbinger of recession"}, {"id": "c", "label": "An expansionary monetary policy"}, {"id": "d", "label": "A coincident indicator"}]'::jsonb, 'Yield curve inversion is a classic leading indicator of recession.'),
  ('1.2-Q15', 'A', 'en', 'Why are rate change expectations often more important than the actual rate decisions themselves?', '[{"id": "a", "label": "Because markets anticipate and price in changes in advance"}, {"id": "b", "label": "Because central banks never change interest rates"}, {"id": "c", "label": "Because interest rates are fixed"}, {"id": "d", "label": "Because expectations have no market impact"}]'::jsonb, 'Markets operate on expectations; being "priced in" is central.'),
  ('1.2-Q2', 'A', 'en', 'The indicator that measures changes in consumer prices is:', '[{"id": "a", "label": "GDP"}, {"id": "b", "label": "NFP"}, {"id": "c", "label": "CPI"}, {"id": "d", "label": "PMI"}]'::jsonb, 'The Consumer Price Index is the standard measure of headline consumer inflation.'),
  ('1.2-Q3', 'A', 'en', 'Higher interest rates tend to:', '[{"id": "a", "label": "Drive away foreign capital"}, {"id": "b", "label": "Attract foreign capital"}, {"id": "c", "label": "Have no impact on the currency"}, {"id": "d", "label": "Reduce inflation immediately"}]'::jsonb, 'Investors seek higher yields, increasing demand for the domestic currency.'),
  ('1.2-Q4', 'A', 'en', 'A trade surplus (exports > imports) means:', '[{"id": "a", "label": "Weaker demand for the domestic currency"}, {"id": "b", "label": "Stronger demand for the domestic currency"}, {"id": "c", "label": "An automatic depreciation"}, {"id": "d", "label": "No impact on forex"}]'::jsonb, 'Foreign buyers need the domestic currency to pay for exports.'),
  ('1.2-Q5', 'A', 'en', 'Non-Farm Payrolls (NFP) measure:', '[{"id": "a", "label": "The number of agricultural jobs"}, {"id": "b", "label": "The number of non-farm jobs created"}, {"id": "c", "label": "The unemployment rate only"}, {"id": "d", "label": "Average hourly earnings"}]'::jsonb, 'NFP measures the net number of non-farm jobs added or lost.'),
  ('1.2-Q6', 'A', 'en', 'High and persistent inflation can lead the central bank to:', '[{"id": "a", "label": "Lower its policy rates"}, {"id": "b", "label": "Raise its policy rates"}, {"id": "c", "label": "Make no change"}, {"id": "d", "label": "Purchase bonds"}]'::jsonb, 'A restrictive monetary policy (rate hikes) aims to curb inflation.'),
  ('1.2-Q7', 'A', 'en', 'Which of the following is a leading indicator?', '[{"id": "a", "label": "Unemployment rate"}, {"id": "b", "label": "GDP"}, {"id": "c", "label": "Building permits"}, {"id": "d", "label": "CPI"}]'::jsonb, 'Building permits turn before the broader economy establishes a trend.'),
  ('1.2-Q8', 'A', 'en', 'Which of the following is a coincident indicator?', '[{"id": "a", "label": "Yield spread (yield curve inversion)"}, {"id": "b", "label": "Industrial production"}, {"id": "c", "label": "Unit labor costs"}, {"id": "d", "label": "New capital goods orders"}]'::jsonb, 'Industrial production moves roughly at the same time as the broader economy.'),
  ('1.2-Q9', 'A', 'en', 'The unemployment rate is considered what type of indicator?', '[{"id": "a", "label": "Leading"}, {"id": "b", "label": "Coincident"}, {"id": "c", "label": "Lagging"}, {"id": "d", "label": "Unreliable"}]'::jsonb, 'Firms wait to be confident in an economic recovery before hiring on a large scale.'),
  ('1.3-Q1', 'A', 'en', 'Microeconomic data primarily focuses on:', '[{"id": "a", "label": "Monetary policy"}, {"id": "b", "label": "Individual company performance"}, {"id": "c", "label": "Foreign exchange rates"}, {"id": "d", "label": "Sentiment and confidence indicators"}]'::jsonb, 'Microeconomics focuses on individual economic units (firms, households).'),
  ('1.3-Q10', 'A', 'en', 'The Current Ratio (current assets / current liabilities) measures:', '[{"id": "a", "label": "Long-term profitability"}, {"id": "b", "label": "Liquidity and the ability to meet short-term obligations"}, {"id": "c", "label": "Operational efficiency"}, {"id": "d", "label": "Revenue growth"}]'::jsonb, 'A ratio < 1 indicates short-term default or liquidity risk.'),
  ('1.3-Q11', 'A', 'en', 'Why can a high ROE driven by financial leverage (debt) be fragile?', '[{"id": "a", "label": "Because debt increases financial risk"}, {"id": "b", "label": "Because debt is always bad"}, {"id": "c", "label": "Because ROE does not account for debt"}, {"id": "d", "label": "Because shareholders dislike debt"}]'::jsonb, 'ROE artificially inflated by debt = increased bankruptcy risk.'),
  ('1.3-Q12', 'A', 'en', 'In balance sheet analysis, "Equity" represents:', '[{"id": "a", "label": "Total liabilities"}, {"id": "b", "label": "The net worth belonging to shareholders"}, {"id": "c", "label": "Fixed assets"}, {"id": "d", "label": "Inventory and receivables"}]'::jsonb, 'Equity = Assets − Liabilities (shareholders'' equity).'),
  ('1.3-Q13', 'A', 'en', 'A company with revenue up 51% (Tesla 2022) but a P/E of 50 is:', '[{"id": "a", "label": "Undervalued"}, {"id": "b", "label": "Potentially overvalued if growth fails to materialize"}, {"id": "c", "label": "Always a good investment"}, {"id": "d", "label": "Risk-free"}]'::jsonb, 'A high P/E prices in future growth that may not materialize.'),
  ('1.3-Q14', 'A', 'en', 'The "Quick Ratio" differs from the "Current Ratio" because it excludes:', '[{"id": "a", "label": "Accounts receivable"}, {"id": "b", "label": "Inventories"}, {"id": "c", "label": "Cash and cash equivalents"}, {"id": "d", "label": "Long-term debt"}]'::jsonb, 'Quick Ratio = (Current Assets − Inventories) / Current Liabilities (more conservative).'),
  ('1.3-Q15', 'A', 'en', 'Why should gross and net margins be analyzed together?', '[{"id": "a", "label": "Because they measure the same thing"}, {"id": "b", "label": "Because the spread between the two reveals operating efficiency and overhead costs"}, {"id": "c", "label": "Because gross margin is sufficient"}, {"id": "d", "label": "Because net margin does not matter"}]'::jsonb, 'Gross margin − operating expenses = net margin. An abnormal spread signals an issue.'),
  ('1.3-Q2', 'A', 'en', 'A company''s balance sheet always satisfies the equation:', '[{"id": "a", "label": "Assets = Liabilities − Equity"}, {"id": "b", "label": "Assets = Liabilities + Equity"}, {"id": "c", "label": "Equity = Liabilities − Assets"}, {"id": "d", "label": "Liabilities = Assets + Equity"}]'::jsonb, 'Assets = Liabilities + Equity (the fundamental accounting equation).'),
  ('1.3-Q3', 'A', 'en', 'The income statement measures:', '[{"id": "a", "label": "Financial health at a specific point in time"}, {"id": "b", "label": "Performance over a period (revenues, expenses, profits)"}, {"id": "c", "label": "Cash flows"}, {"id": "d", "label": "Enterprise value"}]'::jsonb, 'It reports revenues and expenses over a given period.'),
  ('1.3-Q4', 'A', 'en', 'A net margin of 25% means that:', '[{"id": "a", "label": "The company generates 25% net profit relative to its revenue"}, {"id": "b", "label": "The company has 25% debt"}, {"id": "c", "label": "25% of assets are liquid"}, {"id": "d", "label": "ROE is 25%"}]'::jsonb, 'Net margin = Net income / Revenue.'),
  ('1.3-Q5', 'A', 'en', 'The debt-to-equity (D/E) ratio assesses:', '[{"id": "a", "label": "Profitability"}, {"id": "b", "label": "The level of indebtedness"}, {"id": "c", "label": "Liquidity"}, {"id": "d", "label": "Sales growth"}]'::jsonb, 'It indicates the level of debt relative to shareholders'' equity.'),
  ('1.3-Q6', 'A', 'en', 'Return on Equity (ROE) measures:', '[{"id": "a", "label": "The return on shareholders'' equity"}, {"id": "b", "label": "The company''s liquidity"}, {"id": "c", "label": "Total indebtedness"}, {"id": "d", "label": "Revenue growth"}]'::jsonb, 'ROE = Net Income / Shareholders'' Equity.'),
  ('1.3-Q7', 'A', 'en', 'A high Free Cash Flow indicates:', '[{"id": "a", "label": "A strong capacity to generate available cash"}, {"id": "b", "label": "High debt"}, {"id": "c", "label": "Low profitability"}, {"id": "d", "label": "A need for external financing"}]'::jsonb, 'FCF represents the cash generated after capital expenditures (CapEx).'),
  ('1.3-Q8', 'A', 'en', 'In 2023, Apple Inc. posted a net margin of 25% and a P/E of 28. This suggests:', '[{"id": "a", "label": "A fair valuation close to intrinsic value"}, {"id": "b", "label": "A distressed company"}, {"id": "c", "label": "A high D/E ratio"}, {"id": "d", "label": "Low growth"}]'::jsonb, 'High margin + reasonable P/E = valuation aligned with fundamentals.'),
  ('1.3-Q9', 'A', 'en', 'In 2022, Tesla traded at a P/E of 50+. This primarily reflects:', '[{"id": "a", "label": "A discounted valuation"}, {"id": "b", "label": "Very high future growth expectations"}, {"id": "c", "label": "Low volatility"}, {"id": "d", "label": "Zero debt"}]'::jsonb, 'A high P/E indicates that the market is pricing in strong future growth.'),
  ('1.4-Q1', 'A', 'en', 'The Price-to-Earnings (P/E) ratio measures:', '[{"id": "a", "label": "Valuation relative to earnings"}, {"id": "b", "label": "Return on equity"}, {"id": "c", "label": "The level of indebtedness"}, {"id": "d", "label": "Liquidity"}]'::jsonb, 'P/E = Price / EPS. It indicates how many years of earnings are being paid.'),
  ('1.4-Q10', 'A', 'en', 'Peer comparison analysis makes it possible to:', '[{"id": "a", "label": "Identify justified or unjustified valuation gaps"}, {"id": "b", "label": "Forecast foreign exchange rates"}, {"id": "c", "label": "Measure inflation"}, {"id": "d", "label": "Calculate GDP"}]'::jsonb, 'Benchmarking against peers helps detect overvaluation or undervaluation.'),
  ('1.4-Q11', 'A', 'en', 'Why is the DCF model particularly sensitive to WACC?', '[{"id": "a", "label": "Because a +1% shift in WACC = −15% to −20% in valuation"}, {"id": "b", "label": "Because WACC has no impact"}, {"id": "c", "label": "Because WACC is fixed"}, {"id": "d", "label": "Because WACC replaces growth"}]'::jsonb, 'WACC is the most critical input in a DCF model.'),
  ('1.4-Q12', 'A', 'en', 'In Netflix''s SWOT analysis, "Global subscriber base" is a:', '[{"id": "a", "label": "Weakness"}, {"id": "b", "label": "Strength"}, {"id": "c", "label": "Threat"}, {"id": "d", "label": "Opportunity"}]'::jsonb, 'It is a structural competitive advantage.'),
  ('1.4-Q13', 'A', 'en', 'Why can an absolute multiple (e.g., P/E of 30) be misleading?', '[{"id": "a", "label": "Because it depends on the sector and the economic cycle"}, {"id": "b", "label": "Because 30 is always expensive"}, {"id": "c", "label": "Because multiples are useless"}, {"id": "d", "label": "Because the P/E ratio is illegal"}]'::jsonb, 'P/E 30 = expensive (utility) vs. normal (growth tech). Sector context is critical.'),
  ('1.4-Q14', 'A', 'en', 'The "terminal value" in a DCF model typically represents:', '[{"id": "a", "label": "10-20% of the total valuation"}, {"id": "b", "label": "60-80% of the total valuation"}, {"id": "c", "label": "0% of the valuation"}, {"id": "d", "label": "Net debt"}]'::jsonb, 'Most of the value comes from distant cash flows, hence the sensitivity to assumptions.'),
  ('1.4-Q15', 'A', 'en', 'Why does the fundamental analysis of a bank differ from that of a tech company?', '[{"id": "a", "label": "Because banks do not have a balance sheet"}, {"id": "b", "label": "Because key metrics differ (NIM, CET1, provisions vs. ARR, churn)"}, {"id": "c", "label": "Because banks are not publicly traded"}, {"id": "d", "label": "Because fundamental analysis does not apply to banks"}]'::jsonb, 'Each sector has its own ratios and value drivers.'),
  ('1.4-Q2', 'A', 'en', 'The DCF (Discounted Cash Flow) model estimates intrinsic value using:', '[{"id": "a", "label": "Discounted future cash flows"}, {"id": "b", "label": "The average stock price"}, {"id": "c", "label": "Trading volumes"}, {"id": "d", "label": "Analyst sentiment"}]'::jsonb, 'DCF = sum of discounted future FCFs + terminal value.'),
  ('1.4-Q3', 'A', 'en', 'Sector analysis aims to:', '[{"id": "a", "label": "Identify industry-specific trends and challenges"}, {"id": "b", "label": "Predict the price of oil"}, {"id": "c", "label": "Measure inflation"}, {"id": "d", "label": "Calculate GDP"}]'::jsonb, 'It compares performance within a sector to identify leaders and laggards.'),
  ('1.4-Q4', 'A', 'en', 'A SWOT analysis examines:', '[{"id": "a", "label": "Strengths, weaknesses, opportunities, and threats"}, {"id": "b", "label": "Salaries and costs"}, {"id": "c", "label": "Interest rates and inflation"}, {"id": "d", "label": "Volumes and volatility"}]'::jsonb, 'SWOT = qualitative strategic assessment tool.'),
  ('1.4-Q5', 'A', 'en', 'A D/E ratio < 1 is generally interpreted as:', '[{"id": "a", "label": "Excessive leverage"}, {"id": "b", "label": "Reasonable financial health"}, {"id": "c", "label": "Low profitability"}, {"id": "d", "label": "Insufficient liquidity"}]'::jsonb, 'Less debt than equity = conservative capital structure.'),
  ('1.4-Q6', 'A', 'en', 'The P/B (Price-to-Book) ratio compares:', '[{"id": "a", "label": "Share price to book value per share"}, {"id": "b", "label": "Net income to dividends"}, {"id": "c", "label": "Debt to revenue"}, {"id": "d", "label": "Price to cash flow"}]'::jsonb, 'Useful for valuing asset-intensive companies (banks, industrials).'),
  ('1.4-Q7', 'A', 'en', 'In a DCF model, WACC represents:', '[{"id": "a", "label": "Revenue growth rate"}, {"id": "b", "label": "Weighted average cost of capital"}, {"id": "c", "label": "Earnings per share"}, {"id": "d", "label": "Country risk discount rate"}]'::jsonb, 'WACC = weighted average cost of capital, the most sensitive input in a DCF model.'),
  ('1.4-Q8', 'A', 'en', 'Why might Apple''s P/E (28 in 2023) be considered above the sector average?', '[{"id": "a", "label": "Because Apple is bankrupt"}, {"id": "b", "label": "Because the premium reflects quality, ecosystem, and services growth"}, {"id": "c", "label": "Because the tech sector has an average P/E of 50"}, {"id": "d", "label": "Because the P/E ratio does not matter"}]'::jsonb, 'A premium is justified by sustainable competitive advantages.'),
  ('1.4-Q9', 'A', 'en', 'Comparing Tesla vs. Ford (P/E 50 vs. 10) reflects:', '[{"id": "a", "label": "That Ford is always better"}, {"id": "b", "label": "Different growth prospects and risk profiles"}, {"id": "c", "label": "That Tesla is undervalued"}, {"id": "d", "label": "That the P/E ratio is useless"}]'::jsonb, 'A high P/E = expected growth; a low P/E = maturity or distress.'),
  ('1.5-Q1', 'A', 'en', 'Financial forecasts combine:', '[{"id": "a", "label": "Historical data, sector trends, and economic projections"}, {"id": "b", "label": "Only historical data"}, {"id": "c", "label": "Only analyst opinions"}, {"id": "d", "label": "Technical charts only"}]'::jsonb, 'Forecasting is a multi-input process.'),
  ('1.5-Q10', 'A', 'en', 'Why must an invalidation level always be defined prior to entering a position?', '[{"id": "a", "label": "Because it is an AMF regulation"}, {"id": "b", "label": "Because a scenario without an exit leads to confirmation bias"}, {"id": "c", "label": "Because stop-losses are prohibited"}, {"id": "d", "label": "Because invalidation is optional"}]'::jsonb, 'Defining the exit before entering prevents post-hoc rationalization bias.'),
  ('1.5-Q11', 'A', 'en', 'Forecasting gold at $2,000/oz "in the event of geopolitical tensions" is an example of:', '[{"id": "a", "label": "Technical analysis"}, {"id": "b", "label": "A conditional macroeconomic scenario"}, {"id": "c", "label": "Market manipulation"}, {"id": "d", "label": "Historical data"}]'::jsonb, 'This is a forecast contingent upon an external catalyst.'),
  ('1.5-Q12', 'A', 'en', 'Why do the Fed''s interest rate forecasts impact bonds?', '[{"id": "a", "label": "Because bonds are sensitive to interest rates (duration)"}, {"id": "b", "label": "Because the Fed buys bonds"}, {"id": "c", "label": "Because bonds yield zero return"}, {"id": "d", "label": "Because rates are fixed"}]'::jsonb, 'Duration measures the price sensitivity of a bond to interest rate changes.'),
  ('1.5-Q13', 'A', 'en', 'A pessimistic scenario for the automotive industry (-10% in the event of a recession) illustrates:', '[{"id": "a", "label": "The importance of stress testing"}, {"id": "b", "label": "That the automotive sector is risk-free"}, {"id": "c", "label": "That recessions do not exist"}, {"id": "d", "label": "That scenarios are useless"}]'::jsonb, 'Stress testing assesses resilience to macro shocks.'),
  ('1.5-Q14', 'A', 'en', 'The total probability of the three scenarios (bull, base, bear) must be:', '[{"id": "a", "label": "Greater than 100%"}, {"id": "b", "label": "Equal to 100%"}, {"id": "c", "label": "Less than 50%"}, {"id": "d", "label": "Variable depending on the market"}]'::jsonb, 'It represents a complete probability distribution.'),
  ('1.5-Q15', 'A', 'en', 'Why are long-term forecasts (5-10 years) inherently less reliable?', '[{"id": "a", "label": "Because the cumulative uncertainty of assumptions compounds exponentially"}, {"id": "b", "label": "Because analysts are incompetent"}, {"id": "c", "label": "Because historical data does not exist"}, {"id": "d", "label": "Because markets are perfect"}]'::jsonb, 'Small variances in assumptions compound over time.'),
  ('1.5-Q2', 'A', 'en', 'Historical trend analysis aims to:', '[{"id": "a", "label": "Identify patterns in revenue and earnings"}, {"id": "b", "label": "Predict the weather"}, {"id": "c", "label": "Calculate GDP"}, {"id": "d", "label": "Measure inflation"}]'::jsonb, 'It relies on the continuity of past performance.'),
  ('1.5-Q3', 'A', 'en', '"Raised" guidance by a company is generally interpreted as:', '[{"id": "a", "label": "A negative signal"}, {"id": "b", "label": "A positive signal regarding future prospects"}, {"id": "c", "label": "Of no impact"}, {"id": "d", "label": "Market manipulation"}]'::jsonb, 'Management confirms better-than-expected performance.'),
  ('1.5-Q4', 'A', 'en', 'In scenario modeling, analysts typically prepare:', '[{"id": "a", "label": "A single optimistic scenario"}, {"id": "b", "label": "Three scenarios (bull, base, bear)"}, {"id": "c", "label": "A single risk-free scenario"}, {"id": "d", "label": "No scenarios"}]'::jsonb, 'Multi-scenario modeling enables the assessment of risk/reward asymmetry.'),
  ('1.5-Q5', 'A', 'en', 'The "expected value" in a scenario planner is calculated as:', '[{"id": "a", "label": "The simple average of the three scenarios"}, {"id": "b", "label": "Σ(probability × scenario valuation)"}, {"id": "c", "label": "The most probable scenario only"}, {"id": "d", "label": "The median of the scenarios"}]'::jsonb, 'It is the probability-weighted sum of the scenario values.'),
  ('1.5-Q6', 'A', 'en', 'Why is guidance often more important than the current beat/miss?', '[{"id": "a", "label": "Because it shapes the market''s forward-looking expectations"}, {"id": "b", "label": "Because the past does not matter"}, {"id": "c", "label": "Because current earnings reports are inaccurate"}, {"id": "d", "label": "Because guidance is mandatory"}]'::jsonb, 'Markets are forward-looking; lowered guidance can drive down the share price despite an earnings beat.'),
  ('1.5-Q7', 'A', 'en', 'A "risk-free" forecast scenario is:', '[{"id": "a", "label": "Ideal for decision-making"}, {"id": "b", "label": "A dangerous cognitive bias"}, {"id": "c", "label": "Recommended by central banks"}, {"id": "d", "label": "Always accurate"}]'::jsonb, 'Failing to prepare for an adverse scenario means having no exit plan.'),
  ('1.5-Q8', 'A', 'en', 'If a stock''s expected value is higher than its current price, this suggests:', '[{"id": "a", "label": "Positive asymmetry (upside)"}, {"id": "b", "label": "Negative asymmetry (downside)"}, {"id": "c", "label": "That the market is always right"}, {"id": "d", "label": "That one should sell immediately"}]'::jsonb, 'This indicates potential undervaluation based on the model''s assumptions.'),
  ('1.5-Q9', 'A', 'en', 'An EPS beat of 1-2% relative to consensus is generally considered:', '[{"id": "a", "label": "A strong signal"}, {"id": "b", "label": "Minor market noise"}, {"id": "c", "label": "A catastrophe"}, {"id": "d", "label": "A dividend"}]'::jsonb, 'A small deviation may be driven by non-recurring accounting items.'),
  ('1.1-WQ1', 'B', 'en', 'In the MarketDriverVisualizer, the causal chain is displayed as:', '[{"id": "a", "label": "A table of figures"}, {"id": "b", "label": "Driver → Channel → Impacted Asset → Invalidation"}, {"id": "c", "label": "A pie chart"}, {"id": "d", "label": "An alphabetical list"}]'::jsonb, 'The logic is causal transmission with an explicit exit condition.'),
  ('1.1-WQ10', 'B', 'en', 'Why is the MacroRegimeRadar more useful than an isolated macro indicator?', '[{"id": "a", "label": "Because it is more colorful"}, {"id": "b", "label": "Because it forces a multidimensional view (combining multiple factors)"}, {"id": "c", "label": "Because it predicts the exact price"}, {"id": "d", "label": "Because it replaces technical analysis"}]'::jsonb, 'Macro is multifactorial; the radar avoids single-variable diagnoses.'),
  ('1.1-WQ2', 'B', 'en', 'The MacroRegimeRadar displays 4 main regimes. Which one corresponds to "strong growth + moderate inflation"?', '[{"id": "a", "label": "Stagflation"}, {"id": "b", "label": "Recession"}, {"id": "c", "label": "Goldilocks"}, {"id": "d", "label": "Deflation"}]'::jsonb, 'Goldilocks = healthy growth + controlled inflation.'),
  ('1.1-WQ3', 'B', 'en', 'In the MarketDriverVisualizer, "invalidation" represents:', '[{"id": "a", "label": "A calculation error"}, {"id": "b", "label": "The exit condition that renders the thesis void"}, {"id": "c", "label": "A forced buy"}, {"id": "d", "label": "Positive news"}]'::jsonb, 'It is the risk management mechanism: when the thesis is invalidated, you exit.'),
  ('1.1-WQ4', 'B', 'en', 'On the MacroRegimeRadar, the "Liquidity" axis primarily measures:', '[{"id": "a", "label": "Trading volume"}, {"id": "b", "label": "Monetary policy (QE/QT, policy rates)"}, {"id": "c", "label": "The number of employees"}, {"id": "d", "label": "GDP"}]'::jsonb, 'Liquidity = monetary policy, credit spreads, financial conditions.'),
  ('1.1-WQ5', 'B', 'en', 'The "Stagflation" regime on the radar generally implies:', '[{"id": "a", "label": "Bullish equities + bullish bonds"}, {"id": "b", "label": "Low growth + high inflation"}, {"id": "c", "label": "Strong growth + zero inflation"}, {"id": "d", "label": "Deflation + low unemployment"}]'::jsonb, 'Stagflation = economic stagnation + persistent inflation.'),
  ('1.1-WQ6', 'B', 'en', 'In the MarketDriverVisualizer, if the selected driver is "Strong NFP", the transmission channel to the USD is:', '[{"id": "a", "label": "Fiscal policy"}, {"id": "b", "label": "Monetary policy (real rates, Fed expectations)"}, {"id": "c", "label": "Trade balance"}, {"id": "d", "label": "Nothing, NFP does not impact the USD"}]'::jsonb, 'Strong NFP → hawkish Fed → rates ↑ → USD ↑.'),
  ('1.1-WQ7', 'B', 'en', 'The MacroRegimeRadar uses a 6-axis polygon. Which of these axes is NOT displayed?', '[{"id": "a", "label": "GDP"}, {"id": "b", "label": "Inflation"}, {"id": "c", "label": "Policy rates"}, {"id": "d", "label": "Dividends"}]'::jsonb, 'The 6 axes are: GDP, CPI, Rates, Liquidity, Sentiment, Credit.'),
  ('1.1-WQ8', 'B', 'en', 'If the radar indicates a high score on "Inflation" and "Rates", but a low score on "GDP", the likely regime is:', '[{"id": "a", "label": "Expansion"}, {"id": "b", "label": "Stagflation"}, {"id": "c", "label": "Goldilocks"}, {"id": "d", "label": "Pure recession"}]'::jsonb, 'High inflation + low growth = Stagflation.'),
  ('1.1-WQ9', 'B', 'en', 'In the MarketDriverVisualizer, the invalidation of a "Strong GDP" driver could be:', '[{"id": "a", "label": "A downward revision of GDP"}, {"id": "b", "label": "A rise in wages"}, {"id": "c", "label": "A drop in unemployment"}, {"id": "d", "label": "A trade surplus"}]'::jsonb, 'If GDP is revised downward, the strong growth thesis falls apart.'),
  ('1.2-WQ1', 'B', 'en', 'The MacroDashboard displays 11 indicators in the form of:', '[{"id": "a", "label": "A single line chart"}, {"id": "b", "label": "Summary tiles (Actual / Consensus / Previous)"}, {"id": "c", "label": "An Excel spreadsheet"}, {"id": "d", "label": "A geographic map"}]'::jsonb, 'It is a command center with category filters and a detail modal.'),
  ('1.2-WQ10', 'B', 'en', 'On the YieldCurveVisualizer, a "flat" curve suggests:', '[{"id": "a", "label": "Imminent explosive growth"}, {"id": "b", "label": "An economic transition or uncertainty"}, {"id": "c", "label": "Runaway inflation"}, {"id": "d", "label": "A sovereign default"}]'::jsonb, 'Flat curve = market uncertain about the future direction.'),
  ('1.2-WQ11', 'B', 'en', 'In the MacroDashboard, an indicator displaying "Beat" with consensus exceeded means:', '[{"id": "a", "label": "Actual is below consensus"}, {"id": "b", "label": "Actual is above consensus"}, {"id": "c", "label": "Actual equals consensus"}, {"id": "d", "label": "The indicator is cancelled"}]'::jsonb, 'Beat = actual > consensus (positive surprise).'),
  ('1.2-WQ12', 'B', 'en', 'The EconomicCycleWheel allows distinguishing:', '[{"id": "a", "label": "The economic cycle (macro phases) from the price trend (direction)"}, {"id": "b", "label": "The dishwasher cycle"}, {"id": "c", "label": "GDP and inflation only"}, {"id": "d", "label": "Rates and currencies"}]'::jsonb, 'Cycle ≠ trend. The wheel illustrates macro phases, not price charts.'),
  ('1.2-WQ13', 'B', 'en', 'In the FedSimulator, the combination of 5% CPI + 300K NFP likely produces a decision that is:', '[{"id": "a", "label": "Dovish (rate cut)"}, {"id": "b", "label": "Hawkish (rate hike or hold)"}, {"id": "c", "label": "Neutral with no change"}, {"id": "d", "label": "Unlimited QE"}]'::jsonb, 'Hot inflation + strong employment = restrictive Fed.'),
  ('1.2-WQ14', 'B', 'en', 'On the IntermarketCorrelationMap, a breakdown in historical correlation (gray) between gold and the DXY can signal:', '[{"id": "a", "label": "A return to normal"}, {"id": "b", "label": "A systemic shock or a macro regime shift"}, {"id": "c", "label": "A data error"}, {"id": "d", "label": "Nothing in particular"}]'::jsonb, 'Sudden decorrelation = crisis or paradigm shift.'),
  ('1.2-WQ15', 'B', 'en', 'The NfpInterpreter cross-references NFP with average hourly earnings because:', '[{"id": "a", "label": "Wages are merely decorative"}, {"id": "b", "label": "Wage pressure fuels inflation (wage-price spiral)"}, {"id": "c", "label": "Wages have no connection to the Fed"}, {"id": "d", "label": "NFP alone is sufficient"}]'::jsonb, 'NFP + wages = comprehensive read on the labor market for the Fed.'),
  ('1.2-WQ2', 'B', 'en', 'In the EconomicCycleWheel, the "Recession" phase typically favors:', '[{"id": "a", "label": "Cyclical equities"}, {"id": "b", "label": "Gold and sovereign bonds"}, {"id": "c", "label": "Emerging market currencies"}, {"id": "d", "label": "Industrial commodities"}]'::jsonb, 'Recession = flight to quality (safe havens).'),
  ('1.2-WQ3', 'B', 'en', 'The FedSimulator uses two main sliders:', '[{"id": "a", "label": "GDP and trade balance"}, {"id": "b", "label": "CPI and NFP"}, {"id": "c", "label": "Gold and oil"}, {"id": "d", "label": "Equities and bonds"}]'::jsonb, 'The Fed decision matrix crosses inflation and employment.'),
  ('1.2-WQ4', 'B', 'en', 'In the NfpInterpreter, a +2σ (sigma) surprise is interpreted as:', '[{"id": "a", "label": "Statistical noise"}, {"id": "b", "label": "A strong signal likely to trigger a Fed reaction"}, {"id": "c", "label": "Having no market impact"}, {"id": "d", "label": "A lagging indicator"}]'::jsonb, '>2σ = exceptional magnitude = probable institutional reaction.'),
  ('1.2-WQ5', 'B', 'en', 'The YieldCurveVisualizer displays an "inverted" curve when:', '[{"id": "a", "label": "Long-term rates are higher than short-term rates"}, {"id": "b", "label": "Short-term rates are higher than long-term rates (e.g., 2Y > 10Y)"}, {"id": "c", "label": "All rates are zero"}, {"id": "d", "label": "The Fed cuts rates"}]'::jsonb, '2Y/10Y inversion = classic recession signal.'),
  ('1.2-WQ6', 'B', 'en', 'In the GdpCpiInterpreters, the combination of strong GDP + low CPI corresponds to the regime:', '[{"id": "a", "label": "Stagflation"}, {"id": "b", "label": "Goldilocks"}, {"id": "c", "label": "Recession"}, {"id": "d", "label": "Hyperinflation"}]'::jsonb, 'Healthy growth + controlled inflation = ideal environment.'),
  ('1.2-WQ7', 'B', 'en', 'The IntermarketCorrelationMap shows a negative (red) correlation between DXY and EUR/USD. This means:', '[{"id": "a", "label": "When the dollar rises, the euro tends to fall"}, {"id": "b", "label": "Both rise together"}, {"id": "c", "label": "No link between the two"}, {"id": "d", "label": "The correlation is decorative"}]'::jsonb, 'Negative correlation = inverse movements.'),
  ('1.2-WQ8', 'B', 'en', 'In the MacroIndicatorLab, the "surprise" is calculated as:', '[{"id": "a", "label": "Consensus − Actual"}, {"id": "b", "label": "Actual − Consensus"}, {"id": "c", "label": "Actual + Consensus"}, {"id": "d", "label": "Actual / Consensus"}]'::jsonb, 'Surprise = Actual − Consensus (beat if > 0, miss if < 0).'),
  ('1.2-WQ9', 'B', 'en', 'The MacroRelationshipEngine displays a chain: CPI ↑ → Fed hawkish → USD ↑. The transmission mechanism is:', '[{"id": "a", "label": "Contractionary monetary policy strengthens the currency"}, {"id": "b", "label": "Inflation always weakens the currency"}, {"id": "c", "label": "The Fed buys currencies"}, {"id": "d", "label": "The USD rises for no reason"}]'::jsonb, 'Hawkish = rates ↑ → capital attractiveness → currency ↑.'),
  ('1.3-WQ1', 'B', 'en', 'The CompanyHealthScore aggregates 4 dimensions. Which one is NOT included?', '[{"id": "a", "label": "Growth"}, {"id": "b", "label": "Margins"}, {"id": "c", "label": "Debt"}, {"id": "d", "label": "Dividend"}]'::jsonb, 'The 4 dimensions are: Growth, Margins, Debt, Liquidity.'),
  ('1.3-WQ10', 'B', 'en', 'Why is high ROE achieved via leverage (debt) flagged as "fragile" in FinancialRatios?', '[{"id": "a", "label": "Because debt increases financial risk in the event of a shock"}, {"id": "b", "label": "Because debt is prohibited"}, {"id": "c", "label": "Because the ROE is fake"}, {"id": "d", "label": "Because shareholders prefer cash"}]'::jsonb, 'Artificially inflated ROE = bankruptcy risk if interest rates rise.'),
  ('1.3-WQ11', 'B', 'en', 'In BalanceSheetExplorer, a "Current Ratio" < 1 specifically means:', '[{"id": "a", "label": "The company cannot cover its short-term liabilities with its current assets"}, {"id": "b", "label": "The company is highly profitable"}, {"id": "c", "label": "The company has excess cash"}, {"id": "d", "label": "Nothing in particular"}]'::jsonb, 'It is a liquidity warning signal.'),
  ('1.3-WQ12', 'B', 'en', 'Why does the CompanyHealthScore weight "Growth" at 30% and "Liquidity" at 20%?', '[{"id": "a", "label": "Because growth is the best predictor of long-term value creation"}, {"id": "b", "label": "Because liquidity does not matter"}, {"id": "c", "label": "Because the weights are random"}, {"id": "d", "label": "Because debt is more important"}]'::jsonb, 'Growth is the primary driver, but liquidity remains critical (20%).'),
  ('1.3-WQ2', 'B', 'en', 'In the BalanceSheetExplorer, the fundamental equation is:', '[{"id": "a", "label": "Assets = Liabilities + Equity"}, {"id": "b", "label": "Revenue = Earnings + Dividends"}, {"id": "c", "label": "Debt = Assets − Cash"}, {"id": "d", "label": "Equity = Debt × ROE"}]'::jsonb, 'This is the foundation of double-entry bookkeeping.'),
  ('1.3-WQ3', 'B', 'en', 'The CompanyDashboard displays KPIs as:', '[{"id": "a", "label": "Pie chart"}, {"id": "b", "label": "Summary tiles with cross-analysis"}, {"id": "c", "label": "Raw Excel spreadsheet"}, {"id": "d", "label": "Geographic map"}]'::jsonb, 'This provides a rapid executive summary for micro diagnosis.'),
  ('1.3-WQ4', 'B', 'en', 'A CompanyHealthScore > 75 is interpreted as:', '[{"id": "a", "label": "An immediate red flag"}, {"id": "b", "label": "Institutional quality"}, {"id": "c", "label": "An excessive valuation"}, {"id": "d", "label": "A bankruptcy risk"}]'::jsonb, '> 75 indicates a solid company across all 4 dimensions.'),
  ('1.3-WQ5', 'B', 'en', 'In FinancialRatios, an ROE > 15% is generally considered:', '[{"id": "a", "label": "Weak"}, {"id": "b", "label": "Institutional quality"}, {"id": "c", "label": "Negative"}, {"id": "d", "label": "Irrelevant"}]'::jsonb, 'Classic benchmark threshold for return on equity.'),
  ('1.3-WQ6', 'B', 'en', 'The Current Ratio in FinancialRatios measures:', '[{"id": "a", "label": "Profitability"}, {"id": "b", "label": "Short-term liquidity (current assets / current liabilities)"}, {"id": "c", "label": "Total leverage"}, {"id": "d", "label": "Growth"}]'::jsonb, '< 1 indicates short-term default risk.'),
  ('1.3-WQ7', 'B', 'en', 'In the BalanceSheetExplorer, if Assets < Liabilities, the company is:', '[{"id": "a", "label": "Highly profitable"}, {"id": "b", "label": "Technically insolvent"}, {"id": "c", "label": "Growing"}, {"id": "d", "label": "Undervalued"}]'::jsonb, 'Accounting equilibrium is breached, signaling technical insolvency.'),
  ('1.3-WQ8', 'B', 'en', 'The CompanyDashboard suggests that a single KPI "tells no story." Why?', '[{"id": "a", "label": "Because KPIs are inaccurate"}, {"id": "b", "label": "Because Growth + Margins + Debt + Cash must be analyzed together"}, {"id": "c", "label": "Because dashboards are useless"}, {"id": "d", "label": "Because markets are efficient"}]'::jsonb, 'Microeconomic analysis requires considering metrics together (e.g., profitable but overleveraged = fragile).'),
  ('1.3-WQ9', 'B', 'en', 'A D/E ratio < 1 in FinancialRatios indicates:', '[{"id": "a", "label": "More equity than debt"}, {"id": "b", "label": "More debt than equity"}, {"id": "c", "label": "Zero debt"}, {"id": "d", "label": "Imminent bankruptcy"}]'::jsonb, 'Conservative capital structure.'),
  ('1.4-WQ1', 'B', 'en', 'The ValuationLab allows you to test:', '[{"id": "a", "label": "Liquidity ratios"}, {"id": "b", "label": "P/E, P/S, and P/B multiples and their sector premium/discount"}, {"id": "c", "label": "Exchange rates"}, {"id": "d", "label": "Inflation"}]'::jsonb, 'It is a multiples-based valuation laboratory.'),
  ('1.4-WQ10', 'B', 'en', 'In the DcfSimulator, a perpetual growth rate of 6% is:', '[{"id": "a", "label": "Conservative"}, {"id": "b", "label": "Aggressive and likely excessive"}, {"id": "c", "label": "Standard"}, {"id": "d", "label": "Prohibited"}]'::jsonb, 'The perpetual growth rate cannot exceed long-term economic growth (2-4%).'),
  ('1.4-WQ11', 'B', 'en', 'The PeerComparisonMatrix can reveal a "value trap" when:', '[{"id": "a", "label": "The P/E is low but growth is negative and debt is high"}, {"id": "b", "label": "The P/E is high"}, {"id": "c", "label": "The company is the market leader"}, {"id": "d", "label": "The sector is expanding"}]'::jsonb, 'A low multiple justified by deteriorating fundamentals is not a value opportunity.'),
  ('1.4-WQ12', 'B', 'en', 'Why does the EarningsImpactEngine cross-reference the beat/miss with guidance?', '[{"id": "a", "label": "Because guidance shapes future expectations more than past results"}, {"id": "b", "label": "Because the past does not matter"}, {"id": "c", "label": "Because guidance is mandatory"}, {"id": "d", "label": "Because a beat is always positive"}]'::jsonb, 'The market is forward-looking. Guidance drives the readjustment of financial models.'),
  ('1.4-WQ2', 'B', 'en', 'In the DcfSimulator, the most sensitive parameter is:', '[{"id": "a", "label": "Revenue growth"}, {"id": "b", "label": "WACC"}, {"id": "c", "label": "Net margin"}, {"id": "d", "label": "Headcount"}]'::jsonb, '+1% WACC = -15% to -20% in valuation.'),
  ('1.4-WQ3', 'B', 'en', 'The PeerComparisonMatrix compares a company to:', '[{"id": "a", "label": "Peers within the same sector"}, {"id": "b", "label": "Random companies"}, {"id": "c", "label": "Stock market indices"}, {"id": "d", "label": "Central banks"}]'::jsonb, 'It provides a peer-group comparison.'),
  ('1.4-WQ4', 'B', 'en', 'In the EarningsImpactEngine, a "Beat + Guidance Lowered" is generally interpreted as:', '[{"id": "a", "label": "Highly positive"}, {"id": "b", "label": "Often negative (the market prioritizes the forward outlook)"}, {"id": "c", "label": "Neutral"}, {"id": "d", "label": "No impact"}]'::jsonb, 'Guidance outweighs the current beat. Lowered guidance signals an expected deterioration.'),
  ('1.4-WQ5', 'B', 'en', 'The DcfSimulator shows the "terminal value" as representing:', '[{"id": "a", "label": "5% of the valuation"}, {"id": "b", "label": "60-80% of total valuation"}, {"id": "c", "label": "Net debt"}, {"id": "d", "label": "Dividends"}]'::jsonb, 'The majority of the intrinsic value comes from distant cash flows.'),
  ('1.4-WQ6', 'B', 'en', 'In ValuationLab, a multiple above the sector median indicates:', '[{"id": "a", "label": "An automatic discount"}, {"id": "b", "label": "A premium (higher growth or quality)"}, {"id": "c", "label": "A calculation error"}, {"id": "d", "label": "A red flag"}]'::jsonb, 'A premium justified by superior fundamentals.'),
  ('1.4-WQ7', 'B', 'en', 'PeerComparisonMatrix identifies a "laggard" as:', '[{"id": "a", "label": "A company with high ROE and superior margins"}, {"id": "b", "label": "A company with low multiples and compressed margins"}, {"id": "c", "label": "A high-growth company"}, {"id": "d", "label": "A debt-free company"}]'::jsonb, 'Laggard = structural sector underperformer.'),
  ('1.4-WQ8', 'B', 'en', 'In EarningsImpactEngine, an EPS surprise > 5% is considered:', '[{"id": "a", "label": "Market noise"}, {"id": "b", "label": "A strong signal"}, {"id": "c", "label": "Irrelevant"}, {"id": "d", "label": "A special dividend"}]'::jsonb, '> 5% = significant magnitude = probable price reaction.'),
  ('1.4-WQ9', 'B', 'en', 'Why does ValuationLab suggest testing EPS sensitivity by ± 10%?', '[{"id": "a", "label": "Because earnings results are always inaccurate"}, {"id": "b", "label": "To assess valuation robustness against uncertainty"}, {"id": "c", "label": "Because it is mandatory"}, {"id": "d", "label": "To increase the P/E ratio"}]'::jsonb, 'Stress testing assumptions is central to institutional analysis.'),
  ('1.5-WQ1', 'B', 'en', 'ForecastScenarioPlanner uses:', '[{"id": "a", "label": "A single scenario"}, {"id": "b", "label": "3 scenarios (bull, base, bear) + probabilities"}, {"id": "c", "label": "10 identical scenarios"}, {"id": "d", "label": "No scenario"}]'::jsonb, 'Expected value = Σ(probability × scenario valuation).'),
  ('1.5-WQ10', 'B', 'en', 'Why does ScenarioBuilder include an "export" step for the scenario?', '[{"id": "a", "label": "To share and track it in a trading journal"}, {"id": "b", "label": "To print it in color"}, {"id": "c", "label": "Because it is mandatory"}, {"id": "d", "label": "To sell it"}]'::jsonb, 'Exporting enables tracking, post-trade review, and refinement of the decision-making process.'),
  ('1.5-WQ2', 'B', 'en', 'In ScenarioBuilder, a valid scenario must include:', '[{"id": "a", "label": "Only a bullish thesis"}, {"id": "b", "label": "Thesis + transmission mechanism + catalyst + invalidation"}, {"id": "c", "label": "A technical chart"}, {"id": "d", "label": "A buy order"}]'::jsonb, 'Scenario = why + how + when + exit.'),
  ('1.5-WQ3', 'B', 'en', 'The sum of probabilities across the 3 scenarios in ForecastScenarioPlanner must equal:', '[{"id": "a", "label": "50%"}, {"id": "b", "label": "100%"}, {"id": "c", "label": "150%"}, {"id": "d", "label": "Variable"}]'::jsonb, 'It represents a complete probability distribution.'),
  ('1.5-WQ4', 'B', 'en', 'The ScenarioBuilder requires defining an "invalidation" level because:', '[{"id": "a", "label": "It is an AMF regulatory requirement"}, {"id": "b", "label": "Without invalidation = confirmation bias, not a genuine scenario"}, {"id": "c", "label": "Stop-losses are mandatory"}, {"id": "d", "label": "Invalidation is optional"}]'::jsonb, 'Defining the exit before the entry = institutional discipline.'),
  ('1.5-WQ5', 'B', 'en', 'If expected value > current price in the ForecastScenarioPlanner, this suggests:', '[{"id": "a", "label": "Positive asymmetry (upside)"}, {"id": "b", "label": "Overvaluation"}, {"id": "c", "label": "A risk-free scenario"}, {"id": "d", "label": "A calculation error"}]'::jsonb, 'The risk/reward asymmetry favors buying.'),
  ('1.5-WQ6', 'B', 'en', 'In the ScenarioBuilder, the "catalyst" corresponds to:', '[{"id": "a", "label": "The precise moment when the thesis is triggered"}, {"id": "b", "label": "The chart''s color scheme"}, {"id": "c", "label": "The dividend"}, {"id": "d", "label": "The D/E ratio"}]'::jsonb, 'When = triggering event (earnings release, policy decision).'),
  ('1.5-WQ7', 'B', 'en', 'Why does the ForecastScenarioPlanner require 3 scenarios rather than 1?', '[{"id": "a", "label": "Because 1 scenario = absence of risk management"}, {"id": "b", "label": "Because it is required by law"}, {"id": "c", "label": "Because markets are predictable"}, {"id": "d", "label": "Because 3 is a magic number"}]'::jsonb, 'Multi-scenario preparation = anticipating different states of the world.'),
  ('1.5-WQ8', 'B', 'en', 'In the ScenarioBuilder, scenario "validation" corresponds to:', '[{"id": "a", "label": "Acceptance by the central bank"}, {"id": "b", "label": "Conditions confirming that the thesis is materializing"}, {"id": "c", "label": "An algorithm"}, {"id": "d", "label": "An analyst consensus"}]'::jsonb, 'It is the mirror of invalidation: when do I know that I am right?'),
  ('1.5-WQ9', 'B', 'en', 'A 70% probability assigned to the neutral scenario and 15% to each extreme in the ForecastScenarioPlanner suggests:', '[{"id": "a", "label": "High confidence in the base-case scenario"}, {"id": "b", "label": "Extreme uncertainty"}, {"id": "c", "label": "An efficient market"}, {"id": "d", "label": "A modeling error"}]'::jsonb, 'Concentrated distribution = low expected volatility, dominant base case.')
